class LocalD1 implements Database{
 sql=new DatabaseSync(':memory:');constructor(migration:string){this.sql.exec(fs.readFileSync(migration,'utf8'))}
 prepare(sql:string):Statement{const self=this;let values:unknown[]=[];const stmt:Statement={bind(...v:unknown[]){values=v;return stmt},async first<T>(column?:string){const r=self.sql.prepare(sql).get(...values as never[]) as Record<string,unknown>|undefined;return (r?(column?r[column]:r):null) as T|null},async all<T>(){const rows=self.sql.prepare(sql).all(...values as never[]) as T[];return {results:rows,success:true,meta:{}}},async run<T>(){const r=self.sql.prepare(sql).run(...values as never[]);return {results:[],success:true,meta:{changes:Number(r.changes),size_after:Number((self.sql.prepare('PRAGMA page_count').get() as {page_count:number}).page_count)*4096}} as D1Result<T>}};return stmt}
 async batch<T>(s:Statement[]){this.sql.exec('BEGIN');try{const r=[];for(const x of s)r.push(await x.run<T>());this.sql.exec('COMMIT');return r}catch(e){this.sql.exec('ROLLBACK');throw e}}
 async exec(sql:string){this.sql.exec(sql);return {}}
}
function setup(){const db=new LocalD1('migrations/catalog/0001_catalog.sql');for(const f of fs.readdirSync('migrations/catalog').sort().filter(f=>f!=='0001_catalog.sql'))db.sql.exec(fs.readFileSync('migrations/catalog/'+f,'utf8'));const search=new LocalD1('migrations/search/0001_search.sql');for(const f of fs.readdirSync('migrations/search').sort().filter(f=>f!=='0001_search.sql'))search.sql.exec(fs.readFileSync('migrations/search/'+f,'utf8'));return {db,search,env:{CATALOG_DB:db,SEARCH_DB:search,CURSOR_SIGNING_SECRET:'local-test-cursor-secret-at-least32'} as Env}}
test('search ranks the actual subject collection first and searches descriptions, synonyms, typos and age intent',async()=>{
 const {search}=setup(),provider=new D1SearchProvider(search,'search-test-secret-which-is-long');
 const docs=[
  {id:'hibiscus',title:'Hibiscus Garden',tags:'flowers hibiscus',categories:'flowers',description:'A broad hibiscus flower opens.',age_groups:['kids'],recommended_age:'6-8' as const},
  {id:'dragon',title:'Flower Dragon',tags:'dragon flowers',categories:'fantasy',description:'A dragon beside flowers and a turreted castle.',age_groups:['kids'],recommended_age:'9-12' as const},
  {id:'kitten',title:'Sleepy Kitten',tags:'kitten cat',categories:'animals',description:'A kitten asleep beside yarn.',age_groups:['kids'],recommended_age:'6-8' as const},
  {id:'mandala',title:'Botanical Mandala',tags:'mandala petals',categories:'mandalas flowers',description:'Concentric flowers and petals form a pattern.',age_groups:['adults'],recommended_age:'adults' as const},
  {id:'dinosaur',title:'Dinosaur Valley',tags:'dinosaur',categories:'dinosaurs',description:'A long-necked dinosaur.',age_groups:['kids'],recommended_age:'6-8' as const}
 ];
 for(const d of docs)await provider.project({...d,category_ids:d.categories.split(' '),source_version:1,visibility:'published',locale:'en',updated_at:'2026-10-29'});
 const flowers=await provider.search('flower',5);assert.ok(flowers.ids.indexOf('hibiscus')<flowers.ids.indexOf('dragon'));assert.ok(flowers.ids.indexOf('mandala')<flowers.ids.indexOf('dragon'));
 assert.deepEqual((await provider.search('kitty')).ids,['kitten']);assert.deepEqual((await provider.search('turreted castle')).ids,['dragon']);assert.deepEqual((await provider.search('dinosuar')).ids,['dinosaur']);assert.equal((await provider.search('dinosuar')).search_match?.mode,'corrected');
 assert.deepEqual((await provider.search('for adults')).ids,['mandala']);assert.equal((await provider.search('for adults',5,{category:'animals'})).total,0);assert.deepEqual(new Set((await provider.search('age 7')).ids),new Set(['hibiscus','kitten','dinosaur']));assert.equal((await provider.search('fox moon')).total,0);
 await provider.project({...docs[2],category_ids:['animals'],source_version:2,visibility:'archived',locale:'en',updated_at:'2026-10-30'});assert.equal((await provider.search('kitty')).total,0);
});
test('related repository hydrates a bounded published candidate pool and uses indexed tag/category lookups',async()=>{const {db,search,env}=setup();for(let n=0;n<120;n++){const id='related-'+String(n).padStart(3,'0');await add(db,search,id,'Fox '+n,n===4?'draft':n===5?'archived':'published');await db.prepare('INSERT INTO content_tag(content_id,tag) VALUES(?,?)').bind(id,'fox').run();}const repo=new D1CatalogRepository(env,db),source=await repo.get('related-060');assert.ok(source);const result=await repo.related(source);assert.equal(result.collection?.total,118);assert.equal(result.collection?.href,'/coloring-pages/animals/');assert.ok(result.candidateCount<=88);assert.ok(result.matches.length>0);assert.ok(result.matches.every(m=>!['related-060','related-004','related-005'].includes(m.item.id)));assert.deepEqual((await repo.related(source)).matches.map(m=>m.item.id),result.matches.map(m=>m.item.id));const plan=db.sql.prepare('EXPLAIN QUERY PLAN SELECT content_id FROM content_tag WHERE tag=? AND content_id>? ORDER BY content_id LIMIT 8').all('fox',source.id);assert.match(JSON.stringify(plan),/tag_content/);const categoryPlan=db.sql.prepare('EXPLAIN QUERY PLAN SELECT content_id FROM content_category WHERE category_id=? AND content_id>? ORDER BY content_id LIMIT 20').all('animals',source.id);assert.match(JSON.stringify(categoryPlan),/category_content/);});
async function add(db:LocalD1,search:LocalD1,id:string,title:string,status='published',score=100){await db.prepare('INSERT INTO content(id,slug,title,status,active_version,latest_version,published_at,sort_score,provenance_json,difficulty) VALUES(?,?,?,?,?,?,?,?,?,?)').bind(id,id,title,status,1,1,'2026-10-28T10:00:00Z',score,'{}','detailed').run();await db.prepare('INSERT INTO content_category(content_id,category_id) VALUES(?,?)').bind(id,'animals').run();await db.prepare('INSERT INTO content_age(content_id,age) VALUES(?,?)').bind(id,'adults').run();await new D1SearchProvider(search).project({id,source_version:1,visibility:status,locale:'en',title,tags:'fox flowers',categories:'animals',updated_at:'2026-10-28',age_groups:['adults'],category_ids:['animals'],difficulty:'detailed',published_at:'2026-10-28',sort_score:score});}
test('collection covers follow published verified images and update as categories change',async()=>{
 const {db,search,env}=setup(),repo=new D1CatalogRepository(env,db);
 const attach=async(id:string,category:string,verified=1,version=1)=>{await db.prepare('INSERT INTO content_category(content_id,category_id) VALUES(?,?)').bind(id,category).run();await db.prepare('INSERT INTO asset(asset_id,content_id,content_version,role,object_key,original_key,mime,bytes,sha256,asset_version,verified) VALUES(?,?,?,?,?,?,?,?,?,?,?)').bind(id+'-thumb',id,version,'catalog_thumb_bw','published/'+id,'incoming/'+id,'image/webp',100,'a'.repeat(64),version,verified).run()};
 assert.equal(await repo.categoryCover('woodland'),null);
 await add(db,search,'a-draft','Draft','draft');await attach('a-draft','woodland');
 await add(db,search,'b-unverified','Unverified');await attach('b-unverified','woodland',0);
 await add(db,search,'c-wrong-version','Old image');await attach('c-wrong-version','woodland',1,2);
 await add(db,search,'d-pet','Pet');await attach('d-pet','pets');
 assert.equal(await repo.categoryCover('woodland'),null);
 assert.deepEqual((await repo.categoryCovers(['woodland','pets','woodland'])).map(x=>x?.id||null),[null,'d-pet',null]);
 await add(db,search,'e-fox','Fox');await attach('e-fox','woodland');
 assert.equal((await repo.categoryCover('woodland'))?.id,'e-fox');
 assert.ok((await repo.categoryCover('woodland'))?.thumbnail.includes('e-fox'));
 await db.prepare("UPDATE content SET status='archived' WHERE id=?").bind('e-fox').run();
 assert.equal(await repo.categoryCover('woodland'),null);
 assert.equal((await repo.categoryCover('pets'))?.id,'d-pet');
 assert.ok(await repo.categoryCover());
 assert.deepEqual(await repo.categoryCovers([]),[]);
 await assert.rejects(()=>repo.categoryCovers(Array(41).fill('woodland')),AppError);
});
const valid=()=>({schema_version:'1.0',example_only:false,import_action:'create',idempotency_key:'testing-content-1',content_id:'content-one',locale:'en',slug:'one',title:'Fox in flowers',description:'A fox beside flowers.',alt_text:'A fox beside flowers.',requested_status:'draft',category_ids:['animals'],tags:['fox'],provenance:{source_type:'user_owned',rights_status:'documented'},assets:[]});
test('manifest rejects traversal, unknown properties, fake WEBP, and PDFs above 1MB',()=>{assert.equal(safeObjectKey('incoming/a/source.webp'),true);for(const key of ['../a','incoming/../a','incoming/a%2fb','incoming/a\\b','https://a'])assert.equal(safeObjectKey(key),false);assert.throws(()=>validateManifest({...valid(),surprise:true}),AppError);const asset={asset_id:'asset-one',role:'printable_webp_bw',storage_zone:'private_incoming',object_key:'incoming/a/source',mime:'application/pdf',bytes:1000001,sha256:'a'.repeat(64),asset_version:1};assert.throws(()=>validateManifest({...valid(),assets:[asset]}),AppError)});
test('published manifests require all four asset roles and documented non-fixture rights',()=>{assert.throws(()=>validateManifest({...valid(),requested_status:'published'}));assert.throws(()=>validateManifest({...valid(),requested_status:'published',provenance:{source_type:'fixture',rights_status:'test_only'}}));assert.equal(validateManifest(valid()).title,'Fox in flowers')});
test('catalog filters exclude drafts and correlate age/category/total, with stable pagination',async()=>{const {db,search,env}=setup();await add(db,search,'animal-one','One fox','published',200);await add(db,search,'animal-two','Two foxes','published',100);await add(db,search,'hidden-one','Hidden fox','draft',500);const repo=new D1CatalogRepository(env,db,new D1SearchProvider(search));const page=await repo.list({age:['adults'],category:'animals',limit:1});assert.equal(page.total,2);assert.equal(page.items[0].id,'animal-one');assert.ok(page.next_cursor);const second=await repo.list({age:['adults'],category:'animals',limit:1,cursor:page.next_cursor!});assert.equal(second.items[0].id,'animal-two');assert.equal(await repo.get('hidden-one'),null);await assert.rejects(()=>repo.list({age:['kids'],category:'animals',limit:1,cursor:page.next_cursor!}),AppError);assert.equal((await repo.list({age:['kids']})).total,0)});
test('query parsing bounds pages, filters, FTS operators and malformed inputs',()=>{assert.throws(()=>parseCatalogQuery(new URLSearchParams('page=1000000')),AppError);assert.throws(()=>parseCatalogQuery(new URLSearchParams('age=infant')),AppError);assert.equal(ftsQuery('fox OR "rabbit"*'), '"fox"* AND "OR"* AND "rabbit"*');assert.equal(ftsQuery('" OR 1=1 --'), '"OR"* AND "1"* AND "1"*')});
test('FTS search works and an older projection cannot resurrect archived content',async()=>{const {search}=setup();const provider=new D1SearchProvider(search);const base={id:'animal-one',source_version:2,visibility:'published',locale:'en',title:'Woodland fox',tags:'flowers rabbit',categories:'animals',updated_at:'2026-10-28'};await provider.project(base);assert.deepEqual((await provider.search('fox')).ids,['animal-one']);await provider.project({...base,source_version:3,visibility:'archived'});await provider.project({...base,source_version:2});assert.deepEqual((await provider.search('fox')).ids,[]);assert.equal((await search.prepare('SELECT source_version FROM search_document').first<{source_version:number}>())?.source_version,3)});
test('optimistic failed update emits no outbox event; successful update emits exactly one',async()=>{const {db,search}=setup();await add(db,search,'animal-one','Fox');await db.prepare("UPDATE content SET status='archived',latest_version=latest_version+1 WHERE id=? AND latest_version=?").bind('animal-one',99).run();assert.equal((await db.prepare('SELECT COUNT(*) AS n FROM outbox_event').first<{n:number}>())?.n,0);await db.prepare("UPDATE content SET status='archived',latest_version=latest_version+1 WHERE id=? AND latest_version=?").bind('animal-one',1).run();assert.equal((await db.prepare('SELECT COUNT(*) AS n FROM outbox_event').first<{n:number}>())?.n,1)});
test('atomic budget trigger denies a simultaneous excess reservation without creating a second job',async()=>{const {db}=setup();const q='INSERT INTO creator_job(id,owner_id,idempotency_key,payload_sha256,parameters_json,source_revision,model,status,reservation_micros,daily_limit_micros,monthly_limit_micros,concurrent_limit,session_limit,created_at,expires_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)';const create=(id:string)=>db.prepare(q).bind(id,'owner',id,'a','{}','a','model','queued',6000,10000,100000,4,10,'2026-10-28T10:00:00Z','2026-11-04T10:00:00Z').run();const result=await Promise.allSettled([create('one'),create('two')]);assert.equal(result.filter(r=>r.status==='fulfilled').length,1);assert.equal((await db.prepare('SELECT COUNT(*) AS n FROM creator_job').first<{n:number}>())?.n,1)});
test('admin fails closed, origin requires exact same origin, forged session cannot claim a job',async()=>{await assert.rejects(()=>requireAdmin(new Request('https://jot.example/api/admin/status'),{}),AppError);assert.throws(()=>requireOrigin(new Request('https://jot.example/api/creator/jobs',{method:'POST',headers:{Origin:'https://evil.example'}})),AppError);requireOrigin(new Request('https://jot.example/api/creator/jobs',{method:'POST',headers:{Origin:'https://jot.example'}}));await assert.rejects(()=>session(new Request('https://jot.example',{headers:{cookie:'jc_session=forged'}}),{SESSION_SIGNING_SECRET:'x'.repeat(32)},false),AppError)});
test('private session uses signed HttpOnly SameSite cookie and reload maintains owner',async()=>{const env={SESSION_SIGNING_SECRET:'x'.repeat(32)};const first=await session(new Request('https://jot.example'),env,true);assert.match(first.cookie!,/HttpOnly/);assert.match(first.cookie!,/SameSite=Strict/);assert.match(first.cookie!,/Secure/);const next=await session(new Request('https://jot.example',{headers:{Cookie:first.cookie!.split(';')[0]}}),env);assert.equal(first.owner,next.owner)});
test('AI is disabled without explicit bindings and budgets; every visible option reaches prompt',()=>{assert.equal(aiConfiguration({AI_ENABLED:'false'}).ready,false);const p=validateGeneration({mode:'text',prompt:'A fox',style:'cute',line_weight:'bold',detail_level:25,page_shape:'landscape',simplify_background:true});const text=generationPrompt(p);for(const word of ['cute','bold','25/100','landscape','A fox'])assert.ok(text.includes(word));assert.equal(new WorkersAIProvider({}).validateCapabilities().providerIdempotency,false);assert.throws(()=>validateGeneration({...p,detail_level:101}),AppError)});
test('deterministic color preview fills enclosed areas while preserving outlines and source',()=>{const w=24,h=24,raw=new Uint8Array(w*h*4).fill(255);for(let y=2;y<22;y++)for(let x=2;x<22;x++)if(x===2||x===21||y===2||y===21){const p=(y*w+x)*4;raw[p]=raw[p+1]=raw[p+2]=0}const original=raw.slice(),result=colorRegions(raw,w,h);assert.deepEqual([...result.raw.slice(0,4)],[255,255,255,255]);assert.deepEqual([...result.raw.slice((2*w+2)*4,(2*w+2)*4+4)],[0,0,0,255]);assert.notDeepEqual([...result.raw.slice((10*w+10)*4,(10*w+10)*4+3)],[255,255,255]);assert.deepEqual(raw,original);});
test('media sniffing rejects extensions and huge declared image sizes before decoding',()=>{assert.equal(sniffMime(new TextEncoder().encode('<script>not a pdf</script>')),null);assert.equal(sniffMime(new TextEncoder().encode('%PDF-1.7\n')),'application/pdf');const b=new Uint8Array(24);b.set([137,80,78,71,13,10,26,10]);new DataView(b.buffer).setUint32(16,50000);new DataView(b.buffer).setUint32(20,50000);assert.equal(imageDimensions(b).width,50000);assert.throws(()=>normalizePhoto(b),AppError)});
test('canonical payload hashing is independent of object property order',()=>assert.equal(canonicalJSON({b:2,a:{d:4,c:3}}),canonicalJSON({a:{c:3,d:4},b:2})));

test('search paginates beyond eighty results and cursors stay bound to query filters',async()=>{const {db,search,env}=setup();for(let i=0;i<95;i++)await add(db,search,'animal-'+String(i).padStart(3,'0'),'Woodland fox '+i,'published',i);const provider=new D1SearchProvider(search,env.CURSOR_SIGNING_SECRET);const first=await provider.search('fox',48,{category:'animals',age:['adults'],sort:'trending'});assert.equal(first.total,95);assert.equal(first.ids.length,48);assert.ok(first.next_cursor);const next=await provider.search('fox',48,{category:'animals',age:['adults'],sort:'trending',cursor:first.next_cursor!});assert.equal(next.ids.length,47);assert.equal(new Set([...first.ids,...next.ids]).size,95);assert.equal((await provider.search('fox',48,{age:['kids']})).total,0);await assert.rejects(()=>provider.search('fox',48,{category:'flowers',age:['adults'],sort:'trending',cursor:first.next_cursor!}),AppError)});
test('rate limit is atomic, hashes the address, and does not permit an extra concurrent request',async()=>{const {db,env}=setup();env.SESSION_SIGNING_SECRET='x'.repeat(32);const request=new Request('https://example.test',{headers:{'cf-connecting-ip':'192.0.2.1'}});const results=await Promise.allSettled(Array.from({length:7},()=>rateLimit(request,env,'session',6)));assert.equal(results.filter(x=>x.status==='fulfilled').length,6);const row=await db.prepare('SELECT key_hash,count FROM request_limit').first<{key_hash:string;count:number}>();assert.equal(row?.count,7);assert.match(row!.key_hash,/^[a-f0-9]{64}$/);});
test('Access app identity distinguishes approved user and service token subjects',()=>{const env={ADMIN_ALLOWED_SUBJECTS:'owner-uuid',ADMIN_ALLOWED_SERVICE_TOKENS:'import.access'};assert.equal(adminIdentity({type:'app',sub:'owner-uuid'},env),'owner-uuid');assert.equal(adminIdentity({type:'app',sub:'',common_name:'import.access'},env),'service:import.access');assert.throws(()=>adminIdentity({type:'org',sub:'owner-uuid'},env));assert.throws(()=>adminIdentity({type:'app',sub:'',common_name:'other.access'},env));assert.throws(()=>adminIdentity({type:'app',sub:'intruder',common_name:'import.access'},env));});
test('segmented sitemap survives archive and uses bounded stable ordinal ranges',async()=>{const {db,search,env}=setup();await add(db,search,'animal-one','One');await add(db,search,'animal-two','Two');const url=new URL('https://jotcoloring.com/sitemap.xml');const index=await (await sitemapIndex(env,url)).text();assert.match(index,/sitemaps\/1.xml/);assert.match(index,/sitemaps\/static.xml/);await db.prepare("UPDATE content SET status='archived' WHERE id='animal-one'").run();const segment=await (await sitemapSegment(env,url,'1')).text();assert.ok(!segment.includes('animal-one'));assert.ok(segment.includes('animal-two'));await assert.rejects(()=>sitemapSegment(env,url,'99999'),AppError);});
test('sitemap exposes public tools and verified active image URLs, never draft or obsolete assets',async()=>{
 const {db,search,env}=setup();env.PUBLIC_MEDIA_BASE_URL='https://assets.jotcoloring.com';
 const url=new URL('https://jotcoloring.com/sitemap.xml');
 const staticXML=await (await sitemapSegment(env,url,'static')).text();
 assert.match(staticXML,/<loc>https:\/\/jotcoloring.com\/studio\/<\/loc>/);assert.match(staticXML,/<loc>https:\/\/jotcoloring.com\/drawing-board\/<\/loc>/);
 assert.match(staticXML,/<loc>https:\/\/jotcoloring.com\/coloring-pages\/animals\/woodland\/<\/loc>/);
 await add(db,search,'sitemap-live','A fox');await add(db,search,'sitemap-draft','Draft','draft');
 const asset=async(id:string,role:string,key:string,version:number,verified:number)=>db.prepare('INSERT INTO asset(asset_id,content_id,content_version,role,object_key,original_key,mime,bytes,sha256,asset_version,verified) VALUES(?,?,?,?,?,?,?,?,?,?,?)').bind(id+'-'+role+'-'+version,id,version,role,key,'incoming/file','image/webp',10,'a'.repeat(64),version,verified).run();
 await asset('sitemap-live','catalog_preview_bw','fox/preview image.webp',1,1);await asset('sitemap-live','printable_webp_bw','fox/outline.webp',1,1);await asset('sitemap-live','catalog_thumb_bw','fox/old.webp',2,1);await asset('sitemap-draft','catalog_preview_bw','fox/draft.webp',1,1);
 const xml=await (await sitemapSegment(env,url,'1')).text();
 assert.match(xml,/xmlns:image="http:\/\/www.google.com\/schemas\/sitemap-image\/1.1"/);assert.match(xml,/assets\.jotcoloring\.com\/fox\/preview%20image\.webp/);assert.match(xml,/assets\.jotcoloring\.com\/fox\/outline\.webp/);assert.ok(!xml.includes('draft.webp'));assert.ok(!xml.includes('old.webp'));
 await db.prepare("UPDATE content SET status='archived' WHERE id=?").bind('sitemap-live').run();const after=await (await sitemapSegment(env,url,'1')).text();assert.ok(!after.includes('sitemap-live'));assert.ok(!after.includes('outline.webp'));
});

test('draft metadata cannot advance public search version before publication',async()=>{const {db,search,env}=setup();await add(db,search,'animal-one','Old public fox');await db.prepare("UPDATE content SET latest_version=2 WHERE id='animal-one'").run();await db.prepare("INSERT INTO outbox_event(event_id,content_id,version,event_type) VALUES('old-event','animal-one',1,'published')").run();const {projectEvent}=await import('../src/server/imports');await projectEvent(env,'old-event');assert.equal((await search.prepare('SELECT source_version FROM search_document').first<{source_version:number}>())?.source_version,1);await db.prepare("UPDATE content SET active_version=2,title='New public rabbit' WHERE id='animal-one'").run();const event=await db.prepare("SELECT event_id FROM outbox_event WHERE event_id<>'old-event'").first<{event_id:string}>();await projectEvent(env,event!.event_id);assert.equal((await search.prepare('SELECT title FROM search_document').first<{title:string}>())?.title,'New public rabbit');});
test('free-only configuration cannot silently fall back to the paid account AI binding',async()=>{const {freeAIConfiguration}=await import('../src/server/free-ai');const binding={run:async()=>{throw new Error('must not call')}};const env={AI_ENABLED:'true',AI:binding,AI_BILLING_MODE:'free_only' as const,AI_FREE_DAILY_NEURONS:'10000',AI_FREE_MAX_JOB_NEURONS:'300'};assert.equal(freeAIConfiguration(env).ready,false);assert.equal(aiConfiguration(env).ready,false);assert.equal(aiConfiguration(env).reason,'provider_enforced_free_allowance_required');assert.equal(freeAIConfiguration({...env,AI_FREE_GATEWAY_URL:'http://unsafe.example',AI_FREE_GATEWAY_SECRET:'x'.repeat(32)}).ready,false)});
test('signed free gateway accepts bounded configured input and rejects tampered body without inference',async()=>{const {default:gateway}=await import('../workers/free-ai/index');const {gatewayDigest,gatewaySignature,signatureData,GATEWAY_MODEL}=await import('../src/server/gateway-signature');let calls=0;const secret='x'.repeat(40),env={AI:{run:async(model:string,_input:unknown,options?:{returnRawResponse:boolean})=>{assert.equal(model,GATEWAY_MODEL);assert.equal(options?.returnRawResponse,true);calls++;return new Response(JSON.stringify({image:'aGVsbG8='}),{headers:{'Content-Type':'application/json'}})}},AI_FREE_GATEWAY_SECRET:secret,ACCOUNT_BILLING_PLAN:'workers_free',ENFORCED_ACCOUNT_ID:'0dce4e45aa8f6fcab101ea9622db99f2'};const form=new FormData();form.set('prompt','A black ink fox outline on white');form.set('width','1024');form.set('height','1536');const encoded=new Response(form),bytes=new Uint8Array(await encoded.arrayBuffer()),timestamp=String(Date.now()),id=crypto.randomUUID(),hash=await gatewayDigest(bytes);const signature=await gatewaySignature(secret,signatureData(timestamp,id,GATEWAY_MODEL,'300',hash));const headers={'Content-Type':encoded.headers.get('content-type')!,'X-Request-Timestamp':timestamp,'Idempotency-Key':id,'X-AI-Model':GATEWAY_MODEL,'X-Max-Neurons':'300','X-Request-Signature':signature};const ok=await gateway.fetch(new Request('https://gateway.test/inference',{method:'POST',headers,body:bytes}),env);assert.equal(ok.status,200);assert.equal(ok.headers.get('X-Zero-Charge-Enforced'),'true');assert.equal(calls,1);const tampered=bytes.slice();tampered[25]^=1;const bad=await gateway.fetch(new Request('https://gateway.test/inference',{method:'POST',headers,body:tampered}),env);assert.equal(bad.status,401);assert.equal(calls,1);const wrongAccount=await gateway.fetch(new Request('https://gateway.test/inference',{method:'POST',headers,body:bytes}),{...env,ACCOUNT_BILLING_PLAN:'workers_paid'});assert.equal(wrongAccount.status,503);assert.equal(calls,1);const upstreamFailure=await gateway.fetch(new Request('https://gateway.test/inference',{method:'POST',headers,body:bytes}),{...env,AI:{run:async()=>new Response(JSON.stringify({internalCode:3036,description:'private prompt must not escape'}),{status:429,headers:{'Content-Type':'application/json'}})}});assert.deepEqual(await upstreamFailure.json(),{error:'PROVIDER_3036',inference_attempted:true});});
test('home marketing filter requires verified color at the active revision, while catalog remains complete',async()=>{const {db,search,env}=setup();await add(db,search,'animal-one','Colored fox');await add(db,search,'animal-two','Blank rabbit');await add(db,search,'animal-old','Old-color owl');const put=(id:string,version:number)=>db.prepare('INSERT INTO asset(asset_id,content_id,content_version,role,object_key,original_key,mime,bytes,sha256,asset_version,verified) VALUES(?,?,?,?,?,?,?,?,?,?,1)').bind(id+'-color',id,version,'home_half_color','published/key','incoming/key','image/webp',100,'a'.repeat(64),version).run();await put('animal-one',1);await put('animal-old',2);const repo=new D1CatalogRepository(env,db,new D1SearchProvider(search));assert.equal((await repo.list()).total,3);const marketing=await repo.list({marketingOnly:true});assert.equal(marketing.total,1);assert.equal(marketing.items[0].id,'animal-one');assert.ok(marketing.items[0].home_color);});

test('validated import is idempotent through duplicate queue delivery, publish and archive',async()=>{const {db,search,env}=setup();const {default:sharp}=await import('sharp');const {PDFDocument}=await import('pdf-lib');const {acceptReview,reviewSignature,publicAsset}=await import('../src/server/assets');const {createImport,processImport,projectEvent,archiveContent}=await import('../src/server/imports');const {reviewPrintablePDF}=await import('../scripts/data/pdf-review');const {drawPDFBrandFooter}=await import('../src/server/pdf-branding');const {brandedRaster}=await import('../scripts/data/brand-raster');class MemoryBucket{objects=new Map<string,Uint8Array>();async put(key:string,value:Uint8Array|ArrayBuffer|string){this.objects.set(key,typeof value==='string'?new TextEncoder().encode(value):new Uint8Array(value))}async get(key:string){const data=this.objects.get(key);return data?{key,size:data.length,etag:'test',body:new Response(data as BodyInit).body!,arrayBuffer:async()=>data.slice().buffer,text:async()=>new TextDecoder().decode(data)}:null}async head(key:string){return this.get(key)}async delete(key:string|string[]){for(const k of Array.isArray(key)?key:[key])this.objects.delete(k)}}const original=new MemoryBucket(),published=new MemoryBucket(),messages:unknown[]=[];Object.assign(env,{APP_ENV:'production',ORIGINALS:original,PUBLISHED:published,BACKUPS:new MemoryBucket(),MEDIA_VALIDATION_SECRET:'v'.repeat(40),INGEST_QUEUE:{send:async(message:unknown)=>{messages.push(message)}}});const raw=Buffer.alloc(64*64,255);for(let y=10;y<54;y++)for(let x=10;x<54;x++)if(x===10||x===53||y===10||y===53)raw[y*64+x]=0;const sourcePNG=await sharp(raw,{raw:{width:64,height:64,channels:1}}).png().toBuffer();const webp=await sharp(await brandedRaster(sourcePNG,64,64,true)).webp({lossless:true}).toBuffer(),jpeg=await sharp(raw,{raw:{width:64,height:64,channels:1}}).toColourspace('b-w').jpeg().toBuffer();const pdf=await PDFDocument.create(),image=await pdf.embedJpg(jpeg),page=pdf.addPage([595.2756,841.8898]);page.drawImage(image,{x:20,y:53,width:500,height:500});await drawPDFBrandFooter(pdf,page);const document=await pdf.save();await reviewPrintablePDF(document,'printable_pdf_a4_bw');const assets:{asset_id:string}[]=[];for(const role of ['catalog_thumb_bw','catalog_preview_bw','printable_webp_bw','printable_pdf_a4_bw']){const isPDF=role.includes('pdf'),data=isPDF?document:webp,hash=await sha256(data),key='incoming/test/'+role;await original.put(key,data);const a={asset_id:'asset-test-'+role,role,storage_zone:'private_incoming',object_key:key,mime:isPDF?'application/pdf':'image/webp',bytes:data.length,sha256:hash,width:isPDF?null:64,height:isPDF?null:64,page_count:isPDF?1:null,asset_version:1};assets.push(a);const review={sha256:hash,role,mime:a.mime,bytes:a.bytes,width:a.width,height:a.height,page_count:a.page_count,bw:true,reviewed_at:new Date().toISOString(),review_version:3};await acceptReview(env,review,await reviewSignature(review,env.MEDIA_VALIDATION_SECRET!));}const ageReview=syntheticAgeReview(await sha256(webp));const manifest={...valid(),category_selection:preparedCategorySelection(ageReview.category_analysis,ageReview.source_sha256),requested_status:'published',assets,age_recommendation:ageReview};const [a,b]=await Promise.all([createImport(env,manifest,'operator'),createImport(env,manifest,'operator')]);assert.equal(a.job_id,b.job_id);const savedBackups=env.BACKUPS;env.BACKUPS={...savedBackups,put:async()=>{throw new Error('Simulated backup outage')},get:async()=>null} as never;const failed=await Promise.allSettled([processImport(env,a.job_id,'imports/'+a.job_id+'/manifest.json'),processImport(env,a.job_id,'imports/'+a.job_id+'/manifest.json')]);assert.equal(failed.filter(r=>r.status==='rejected').length,1);assert.equal((await db.prepare('SELECT status FROM content').first<{status:string}>())?.status,'draft');assert.equal(published.objects.size,0);env.BACKUPS=savedBackups;await Promise.all([processImport(env,a.job_id,'imports/'+a.job_id+'/manifest.json'),processImport(env,a.job_id,'imports/'+a.job_id+'/manifest.json')]);assert.equal((await db.prepare('SELECT COUNT(*) AS n FROM content').first<{n:number}>())?.n,1);assert.equal((await db.prepare('SELECT status FROM import_job').first<{status:string}>())?.status,'completed');assert.equal((await db.prepare('SELECT COUNT(*) AS n FROM content_revision').first<{n:number}>())?.n,1);const event=await db.prepare('SELECT event_id FROM outbox_event').first<{event_id:string}>();await projectEvent(env,event!.event_id);const repo=new D1CatalogRepository(env,db,new D1SearchProvider(search));assert.equal((await repo.get('content-one'))?.title,'Fox In Flowers');assert.equal((await repo.get('content-one'))?.recommendedAge?.band,'3-5');assert.equal((await repo.list({recommended_age:'3-5'})).total,1);assert.equal((await repo.list({recommended_age:'adults'})).total,0);assert.equal((await repo.list({q:'fox',recommended_age:'3-5'})).total,1);assert.equal((await repo.list({q:'fox',recommended_age:'adults'})).total,0);assert.equal((await repo.list({q:'fox'})).total,1);const media=await publicAsset(new Request('https://jot.test/api/download/content-one/pdf'),env,'content-one','printable_pdf_a4_bw',true);assert.equal(media.headers.get('Content-Type'),'application/pdf');assert.equal((await media.arrayBuffer()).byteLength,document.length);await assert.rejects(()=>publicAsset(new Request('https://jot.test/file?v='+('f'.repeat(24))),env,'content-one','printable_pdf_a4_bw'),(error:unknown)=>error instanceof AppError&&error.status===410);await archiveContent(env,'content-one',1,'operator');for(const event of (await db.prepare('SELECT event_id FROM outbox_event WHERE processed_at IS NULL').all<{event_id:string}>()).results)await projectEvent(env,event.event_id);assert.equal(await repo.get('content-one'),null);assert.equal((await repo.list({q:'fox'})).total,0);await assert.rejects(()=>publicAsset(new Request('https://jot.test'),env,'content-one','printable_pdf_a4_bw'),AppError);const {prepareUpdateManifest,availableContentActions}=await import('../src/ui/admin-content');assert.deepEqual(availableContentActions({status:'archived',latest_version:2,active_version:1,revision_ready:0}),['Edit']);const update=prepareUpdateManifest(manifest as any,2);update.title='Fox restored';assert.equal(new Set(update.assets.map(x=>x.asset_id)).size,4);assert.ok(update.assets.every(x=>!assets.some(old=>old.asset_id===x.asset_id)));const restore=await createImport(env,update,'operator');await processImport(env,restore.job_id,'imports/'+restore.job_id+'/manifest.json');assert.equal((await db.prepare('SELECT status,latest_version FROM content WHERE id=?').bind('content-one').first<{status:string;latest_version:number}>())?.latest_version,3);assert.equal(await repo.get('content-one'),null);const {publishContent}=await import('../src/server/imports');await publishContent(env,'content-one',3,'operator');for(const event of (await db.prepare('SELECT event_id FROM outbox_event WHERE processed_at IS NULL').all<{event_id:string}>()).results)await projectEvent(env,event.event_id);assert.equal((await repo.get('content-one'))?.title,'Fox Restored');assert.equal((await repo.list({q:'restored'})).total,1);});
test('cancelling a queued private job prevents inference and cannot expose another owner result',async()=>{const {env,db}=setup();const {createGeneration,cancelGeneration,runGeneration,generationStatus,generationResult}=await import('../src/server/ai');let providerCalls=0;Object.assign(env,{AI_ENABLED:'true',AI_BILLING_MODE:'free_only',AI_FREE_DAILY_NEURONS:'9000',AI_FREE_MAX_JOB_NEURONS:'1000',AI_MAX_CONCURRENT_JOBS:'1',AI_PER_SESSION_DAILY_LIMIT:'2',AI_MODEL_ID:'@cf/black-forest-labs/flux-2-klein-4b',AI_FREE_ONLY_GATEWAY:{fetch:async()=>{providerCalls++;return new Response()}},AI_QUEUE:{send:async()=>{}},JOB_ASSETS:{},SESSION_SIGNING_SECRET:'s'.repeat(40)});const parameters={mode:'text',prompt:'A rabbit',style:'simple',line_weight:'bold',detail_level:20,page_shape:'portrait',simplify_background:true};const job=await createGeneration(env,'owner-a',parameters,'private-test-one');assert.equal(job.state,'queued');await assert.rejects(()=>generationStatus(env,'owner-b',job.job_id),AppError);await assert.rejects(()=>cancelGeneration(env,'owner-b',job.job_id),AppError);assert.equal((await cancelGeneration(env,'owner-a',job.job_id)).state,'cancelled');await runGeneration(env,job.job_id);assert.equal(providerCalls,0);const repeat=await createGeneration(env,'owner-a',parameters,'private-test-one');assert.equal(repeat.job_id,job.job_id);assert.equal(repeat.state,'cancelled');assert.equal((await db.prepare('SELECT COUNT(*) AS n FROM creator_job').first<{n:number}>())?.n,1);await assert.rejects(()=>generationResult(new Request('https://jot.test/result'),env,'owner-a',job.job_id),AppError);});

