test('AI print processing embeds actual grayscale artwork independently of its colored footer',async()=>{
 const {default:sharp}=await import('sharp');const {processLineArt}=await import('../src/server/image-processing');const {PDFDocument,PDFName,PDFRawStream}=await import('pdf-lib');const {inflateSync}=await import('node:zlib');
 const width=96,height=128,gray=Buffer.alloc(width*height,255);for(let y=20;y<100;y++)for(let x=20;x<76;x++)if(x<24||x>71||y<24||y>95)gray[y*width+x]=0;
 const source=await sharp(gray,{raw:{width,height,channels:1}}).png().toBuffer();const result=await processLineArt(source);assert.equal(result.hasBrandFooter,true);assert.ok(result.pdf.length<=1_000_000);
 const document=await PDFDocument.load(result.pdf);assert.equal(document.getPageCount(),1);let found=0,logos=0;const {brandLogoRGB}=await import('../src/server/branding');for(const [,object]of document.context.enumerateIndirectObjects())if(object instanceof PDFRawStream&&object.dict.get(PDFName.of('Subtype'))===PDFName.of('Image')){if(object.dict.get(PDFName.of('ColorSpace'))===PDFName.of('DeviceGray')){found++;assert.deepEqual(inflateSync(object.getContents()),gray)}else{logos++;assert.equal(object.dict.get(PDFName.of('ColorSpace')),PDFName.of('DeviceRGB'));assert.deepEqual(inflateSync(object.getContents()),Buffer.from(brandLogoRGB()))}}assert.equal(found,1);assert.equal(logos,1);
});

